import {activities,assess,decide,curriculumVersion} from './curriculum.js';
const KEY='everyday-english-v1';
const initial=()=>({version:curriculumVersion,index:0,attempts:{},evidence:[],completed:false,updated:null});
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved?.version===curriculumVersion?{...initial(),...saved}:initial()}catch{state=initial()}
let view='home',cameraStream=null,recognition=null,recognized='',busy=false,feedback='',selected=-1,french=true,showPhrase=true;
const root=document.querySelector('#app');
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){state.updated=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state))}
function announce(s){const e=document.getElementById('live-status');if(e)e.textContent=s}
function shell(content,active){root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">✦</div>Everyday English</div><div class="tagline">A little English, every day.<br>Learn to understand. Learn to connect.</div><nav aria-label="Main navigation"><button class="navbtn ${active==='home'?'active':''}" data-nav="home">⌂ <span>My learning</span></button><button class="navbtn ${active==='lesson'?'active':''}" data-nav="lesson">▤ <span>Practice</span></button><button class="navbtn ${active==='progress'?'active':''}" data-nav="progress">◉ <span>My progress</span></button></nav><div class="sidebar-bottom">Made for one learner, at his own pace.<br>No streaks. No pressure.</div></aside><main class="content"><div class="topline"><span>PERSONAL ENGLISH COMPANION</span><span class="pill">● Foundation · Beginner</span></div>${content}<p class="footer-note">Private prototype · Progress is saved in this browser only. Camera video stays on this device and is not analyzed or uploaded. Audio pronunciation uses your browser; speech recognition availability varies.</p><div id="live-status" role="status" aria-live="polite" class="sr-only"></div></main></div>`;root.querySelectorAll('[data-nav]').forEach(x=>x.onclick=()=>navigate(x.dataset.nav))}
function navigate(where){if(where!=='lesson')stopCamera();view=where;feedback='';render()}
function render(){if(view==='home')return home();if(view==='progress')return progress();lesson()}
function home(){const done=state.evidence.filter(e=>e.correct).length;const count=state.evidence.length;shell(`<section class="hero"><div class="lesson-hero"><div><span class="eyebrow">YOUR ENGLISH JOURNEY</span><h1>Bonjour !<br>Let's learn together.</h1><p>We'll take it one conversation at a time. Listen, understand, speak, and feel more comfortable using English every day.</p></div><button class="btn" id="start">${state.index>0?'Continue learning':'Begin your first lesson'} &nbsp; →</button></div><div class="panel"><div class="eyebrow">TODAY'S FOCUS</div><h2>Meeting someone new</h2><p class="muted">We'll listen to greetings, understand simple questions, and practice introducing ourselves.</p><div class="divider"></div><span class="subtle">FIRST LEARNING UNIT</span><div class="progress-track"><div class="progress-fill" style="width:${state.index/activities.length*100}%"></div></div><div class="subtle">${Math.min(state.index,activities.length)} of ${activities.length} activities explored</div><div class="stats"><div class="stat"><strong>${count}</strong><small>Practice attempts</small></div><div class="stat"><strong>${done}</strong><small>Successful responses*</small></div></div><p class="footer-note">*These are practice observations, not proof of mastery.</p></div></section>`, 'home');document.getElementById('start').onclick=()=>navigate('lesson')}
function lesson(){if(state.completed||state.index>=activities.length)return finish();const a=activities[state.index];const options=a.type==='choice'?`<div class="options" role="group" aria-label="Choose what you understood">${a.options.map((o,i)=>`<button class="option ${selected===i?'selected':''}" data-option="${i}">${escapeHtml(o.label)}</button>`).join('')}</div>`:`<div><button class="btn secondary" id="speak">🎙 Speak your answer</button><p class="subtle" id="speech-status">Microphone speech recognition may not be available in every browser. You can type instead.</p><label for="answer" class="subtle">Your answer (spoken text or typed)</label><input id="answer" class="textarea" autocomplete="off" placeholder="For example: Hello, my name is…" value="${escapeHtml(recognized)}"></div>`;
shell(`<div class="lesson-layout"><section class="panel lesson-card"><div class="step-row"><span class="eyebrow">${escapeHtml(a.stage)} · ACTIVITY ${state.index+1} OF ${activities.length}</span><span class="subtle">Take your time</span></div><div class="progress-track"><div class="progress-fill" style="width:${state.index/activities.length*100}%"></div></div><h2>${escapeHtml(a.title)}</h2><p class="muted">${escapeHtml(a.instruction)}</p><div class="word-card"><button class="listen-btn" id="listen" title="Listen to English" aria-label="Listen to English">▶</button><div class="phrase" id="phrase">${showPhrase?escapeHtml(a.prompt):'Listen carefully…'}</div><div class="translation" id="translation">${french?escapeHtml(a.french):'French help is hidden'}</div></div>${options}<div id="feedback" aria-live="polite">${feedback?`<div class="feedback ${feedback.includes('Try')?'warn':''}">${escapeHtml(feedback)}</div>`:''}</div><div class="actions"><button class="btn" id="check">Check my answer →</button><button class="btn ghost" id="hear-again">↻ Hear again</button><button class="btn secondary" id="need-help">I need help / J'ai besoin d'aide</button></div></section><aside class="panel"><h3>Your learning tools</h3><label class="toggle-line"><input id="french" type="checkbox" ${french?'checked':''}/> French explanations</label><label class="toggle-line"><input id="showphrase" type="checkbox" ${showPhrase?'checked':''}/> Show English text</label><div class="divider"></div><h3>Camera preview <span class="subtle">(optional)</span></h3><div class="camera-box" id="camera-box"><span>📷 Camera is off</span></div><div class="actions"><button class="btn secondary" id="camera-start">Turn on camera</button><button class="btn ghost" id="camera-stop" disabled>Turn off</button></div><p class="subtle">Preview only. This version does not send video to AI or infer your feelings or understanding.</p><div class="divider"></div><h3>At your pace</h3><p class="muted" style="font-size:14px">You can repeat a question, ask for French help, or continue after trying. No timer and no streak.</p><button class="btn ghost" id="skip">Continue without scoring →</button></aside></div>`,'lesson');
document.getElementById('listen').onclick=()=>play(a.prompt);document.getElementById('hear-again').onclick=()=>play(a.prompt);document.getElementById('check').onclick=()=>check(a);document.getElementById('need-help').onclick=()=>{feedback=`En français : ${a.french} Essayez encore, à votre rythme.`;french=true;render()};document.getElementById('french').onchange=e=>{french=e.target.checked;render()};document.getElementById('showphrase').onchange=e=>{showPhrase=e.target.checked;render()};document.getElementById('camera-start').onclick=startCamera;document.getElementById('camera-stop').onclick=stopCamera;document.getElementById('skip').onclick=()=>advance(a,false,'skipped');document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.option);document.querySelectorAll('[data-option]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.option)===selected))});if(a.type==='speak')document.getElementById('speak').onclick=startSpeech;
if(cameraStream)attachCamera();}
function play(text){if(!('speechSynthesis'in window)){feedback='This browser does not support speech playback.';render();return}speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(text);utter.lang='en-US';utter.rate=.83;utter.pitch=1;const voices=speechSynthesis.getVoices();utter.voice=voices.find(v=>v.lang==='en-US')||null;speechSynthesis.speak(utter)}
function check(a){if(busy)return;const response=a.type==='choice'?selected:document.getElementById('answer')?.value||'';if(response===-1||!String(response).trim()){feedback='Try an answer first, or choose “I need help”.';render();return}const outcome=assess(a,response);const n=(state.attempts[a.id]||0)+1;state.attempts[a.id]=n;state.evidence.push({activityId:a.id,skill:a.skill,correct:outcome.correct,confidence:outcome.confidence,reason:outcome.reason,assisted:french,at:new Date().toISOString(),responseType:a.type});persist();const action=decide(n,outcome.correct);if(action==='continue'){feedback='Good work. Let’s try the next situation.';advance(a,true,'attempt')}else if(action==='scaffold'){feedback='Let’s practice this in a different way. The French meaning is now visible. You can try again, or continue.';french=true;showPhrase=true;render()}else{feedback='Try once more. Listen again or ask for French help.';render()}}
function advance(a,correct,reason){if(reason==='skipped'){state.evidence.push({activityId:a.id,skill:a.skill,correct:false,confidence:'none',reason:'Skipped without assessment',assisted:false,at:new Date().toISOString()})}state.index=Math.min(activities.length,state.index+1);state.completed=state.index>=activities.length;persist();selected=-1;recognized='';feedback='';stopSpeech();render()}
function finish(){shell(`<section class="hero"><div class="lesson-hero"><div><span class="eyebrow">UNIT 01 · SESSION COMPLETE</span><h1>You showed up.<br>That's what matters.</h1><p>You've explored introductions. What matters next is whether you can recognize and use these exchanges again, with new people and new wording.</p></div><div class="actions"><button class="btn" id="revisit">Practice again ↻</button><button class="btn secondary" id="review-progress">See my learning notes</button></div></div><div class="panel"><h2>Not a final score.</h2><p class="muted">This is an early guided practice session. We haven't tested long-term retention, spontaneous real-world conversation, or pronunciation reliability yet.</p><p class="muted">Next planned improvement: a true AI tutor that follows up in a fresh conversation and remembers what was difficult.</p></div></section>`,'lesson');document.getElementById('revisit').onclick=()=>{state.index=0;state.completed=false;state.attempts={};persist();render()};document.getElementById('review-progress').onclick=()=>navigate('progress')}
function progress(){const grouped={};state.evidence.forEach(e=>{const s=grouped[e.skill]||{attempts:0,success:0};s.attempts++;if(e.correct)s.success++;grouped[e.skill]=s});shell(`<h1>My learning notes</h1><p class="muted">Here you'll see what you've practiced and what needs more work. These are not official proficiency scores.</p><div class="hero"><section class="panel"><div class="eyebrow">OBSERVED PRACTICE</div><h2>Foundation: Introductions</h2><p class="muted">${state.evidence.length} attempts logged across ${Object.keys(grouped).length} different communication skills.</p><div class="history">${Object.entries(grouped).length?Object.entries(grouped).map(([skill,v])=>`<div class="history-row"><span>${escapeHtml(skill.replaceAll('-',' '))}</span><small>${v.success} / ${v.attempts} guided responses</small></div>`).join(''):'<p>No practice recorded yet. Start the first lesson whenever you are ready.</p>'}</div></section><section class="panel"><h3>How memory works right now</h3><p class="muted">Progress is stored only on this browser using localStorage. It does not sync across devices, and it is not yet reviewed by an AI.</p><div class="divider"></div><button id="export" class="btn secondary">Download my learning record</button><div style="height:12px"></div><button id="reset" class="btn ghost">Clear this browser's progress</button></section></div>`,'progress');document.getElementById('export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='english-learning-record.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};document.getElementById('reset').onclick=()=>{if(confirm('Clear all learning progress stored in this browser? This cannot be undone.')){state=initial();persist();navigate('home')}}}
async function startCamera(){if(!navigator.mediaDevices?.getUserMedia){feedback='Camera access requires HTTPS or localhost and a compatible browser.';render();return}try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});attachCamera()}catch(e){feedback='Camera could not start. Check permission or whether another app is using it.';render()}}
function attachCamera(){const box=document.getElementById('camera-box');if(!box||!cameraStream)return;box.replaceChildren();const v=document.createElement('video');v.autoplay=true;v.playsInline=true;v.muted=true;v.srcObject=cameraStream;box.appendChild(v);const lbl=document.createElement('div');lbl.className='camera-label';lbl.textContent='Local preview · Not transmitted';box.appendChild(lbl);const on=document.getElementById('camera-start'),off=document.getElementById('camera-stop');if(on)on.disabled=true;if(off)off.disabled=false}
function stopCamera(){if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}const box=document.getElementById('camera-box');if(box)box.innerHTML='<span>📷 Camera is off</span>';const on=document.getElementById('camera-start'),off=document.getElementById('camera-stop');if(on)on.disabled=false;if(off)off.disabled=true}
function startSpeech(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;const msg=document.getElementById('speech-status');if(!Speech){if(msg)msg.textContent='Speech recognition is unavailable in this browser. Type your answer instead.';return}stopSpeech();recognition=new Speech();recognition.lang='en-US';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onresult=e=>{recognized=e.results[0][0].transcript;const input=document.getElementById('answer');if(input)input.value=recognized;if(msg)msg.textContent='Heard: '+recognized+' · Please check the text before submitting.'};recognition.onerror=e=>{if(msg)msg.textContent='Could not recognize speech ('+e.error+'). You may type instead.'};recognition.onend=()=>{recognition=null};try{recognition.start();if(msg)msg.textContent='Listening… speak naturally.'}catch{if(msg)msg.textContent='Microphone could not start. Type your answer instead.'}}
function stopSpeech(){if(recognition){recognition.onend=null;recognition.abort();recognition=null}}
window.addEventListener('pagehide',()=>{stopCamera();stopSpeech();if('speechSynthesis'in window)speechSynthesis.cancel()});if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{})}render();
